  for(let i=0;i<9;i++){
    const p=((i/9+t/9)%1);const q=p*p;const y=g.hy+(g.gy-g.hy)*q;const sc=.12+.9*q;
    for(const s of [-1,1]){
      const x=g.cx+s*(g.topw*.67+(g.bw*.61-g.topw*.67)*q);
      ctx.fillStyle='#273b49';ctx.fillRect(x-4*sc,y-36*sc,8*sc,40*sc);
      ctx.fillStyle=i%3===0?'#ffb25f':'#e9d8b7';ctx.fillRect(x-7*sc,y-38*sc,14*sc,5*sc);
    }
  }
}
function shadow(x,y,rx,ry,alpha=.3){ctx.fillStyle=`rgba(8,18,28,${alpha})`;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function drawCoin(o){
  const p=project(o.z), x=laneX(o.lane,o.z), s=p.scale, bob=Math.sin(elapsed*8+o.phase)*3*s, r=11*s;
  shadow(x,p.y+5*s,r*1.35,r*.45,.2);
  ctx.save();ctx.translate(x,p.y-17*s+bob);ctx.scale(.72+Math.abs(Math.sin(elapsed*7+o.phase))*.28,1);
  ctx.fillStyle='#ffd45e';ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff0a5';ctx.lineWidth=2*s;ctx.stroke();
  ctx.fillStyle='#e99c34';ctx.font=`900 ${r*1.15}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('✦',0,1*s);ctx.restore();
}
function drawObstacle(o){
  const p=project(o.z), x=laneX(o.lane,o.z), y=p.y, s=p.scale;
  if(o.type==='train'){
    const w=104*s,h=108*s;shadow(x,y+5*s,w*.58,10*s,.35);
    ctx.fillStyle='#182a3a';rounded(x-w/2+5*s,y-h+5*s,w,h,12*s);ctx.fill();
    const body=ctx.createLinearGradient(x-w/2,y-h,x+w/2,y);body.addColorStop(0,'#ffb36b');body.addColorStop(.55,'#ef785f');body.addColorStop(1,'#b64f60');ctx.fillStyle=body;rounded(x-w/2,y-h,w,h,12*s);ctx.fill();
    ctx.fillStyle='#273e51';rounded(x-w/2+10*s,y-h+13*s,w-20*s,34*s,6*s);ctx.fill();
    for(let i=0;i<3;i++){ctx.fillStyle='#94d4d0';rounded(x-w/2+14*s+i*25*s,y-h+18*s,19*s,22*s,3*s);ctx.fill()}
    ctx.fillStyle='#ffe7a7';rounded(x-w/2+12*s,y-27*s,18*s,9*s,3*s);ctx.fill();rounded(x+w/2-30*s,y-27*s,18*s,9*s,3*s);ctx.fill();
    ctx.fillStyle='#334a5b';rounded(x-w/2+11*s,y-10*s,w-22*s,9*s,4*s);ctx.fill();
  }else if(o.type==='barrier'){
    const w=70*s,h=48*s;shadow(x,y+4*s,w*.58,8*s,.32);
    ctx.fillStyle='#3b4751';ctx.fillRect(x-w*.39,y-h*.28,8*s,h*.75);ctx.fillRect(x+w*.29,y-h*.28,8*s,h*.75);
    ctx.fillStyle='#ff9f55';rounded(x-w/2,y-h,w,h*.58,5*s);ctx.fill();
    ctx.save();ctx.beginPath();ctx.rect(x-w/2,y-h,w,h*.58);ctx.clip();for(let i=-2;i<5;i++)polygon([[x-w/2+i*19*s,y-h],[x-w/2+(i+1)*19*s,y-h],[x-w/2+(i+1)*19*s-20*s,y-h*.42],[x-w/2+i*19*s-20*s,y-h*.42]],'#fff0d6');ctx.restore();
    ctx.fillStyle='#334756';ctx.font=`900 ${9*s}px system-ui`;ctx.textAlign='center';ctx.fillText('JUMP',x,y-h*.14);
  }else if(o.type==='beam'){
    const w=91*s,h=88*s;shadow(x,y+4*s,w*.55,8*s,.25);
    ctx.fillStyle='#4b6270';ctx.fillRect(x-w*.42,y-h,8*s,h);ctx.fillRect(x+w*.33,y-h,8*s,h);
    ctx.fillStyle='#28a6ac';rounded(x-w/2,y-h,w,h*.32,5*s);ctx.fill();
    ctx.fillStyle='#c2fbeb';ctx.font=`900 ${8*s}px system-ui`;ctx.textAlign='center';ctx.fillText('SLIDE',x,y-h*.6);
    ctx.fillStyle='#ffd45e';ctx.fillRect(x-w*.42,y-h-4*s,w*.84,4*s);
  }
}
function drawPlayer(){
  const g=geometry(), ground=g.gy+2, x=laneX(laneVisual,0), air=Math.sin(Math.PI*clamp(jump/.72,0,1))*Math.min(H*.16,105), isSliding=slide>0;
  const run=Math.sin(elapsed*13), s=clamp(Math.min(W/700,H/600),.72,1.15), foot=ground-air;
  shadow(x,ground+5,28*s*(1-air/240),9*s*(1-air/240),.32);
  ctx.save();ctx.translate(x,foot);if(isSliding)ctx.translate(0,8*s);
