    const swing=jump>0?-.3:run*.44;
    ctx.strokeStyle='#20384f';ctx.lineWidth=12*s;ctx.lineCap='round';
    line(x*0,0,0,0,'transparent',1); // keep canvas path state local
    ctx.beginPath();ctx.moveTo(-7*s,-34*s);ctx.lineTo((-11+swing*13)*s,-8*s);ctx.lineTo((-12+swing*20)*s,0);ctx.stroke();
    ctx.beginPath();ctx.moveTo(7*s,-34*s);ctx.lineTo((11-swing*13)*s,-8*s);ctx.lineTo((12-swing*20)*s,0);ctx.stroke();
    ctx.fillStyle='#f4ead2';rounded((-21+swing*20)*s,-4*s,19*s,7*s,3*s);ctx.fill();rounded((3-swing*20)*s,-4*s,19*s,7*s,3*s);ctx.fill();
  }else{
    ctx.fillStyle='#20384f';rounded(-29*s,-20*s,58*s,19*s,9*s);ctx.fill();ctx.fillStyle='#f4ead2';rounded(17*s,-9*s,18*s,6*s,3*s);ctx.fill();
  }
