  ctx.fillStyle='#ff9e59';rounded(-17*s,bodyY,34*s,39*s,10*s);ctx.fill();
  ctx.fillStyle='#ffca76';rounded(-3*s,bodyY+4*s,7*s,29*s,3*s);ctx.fill();
  // arms swing
  ctx.strokeStyle='#ffca9b';ctx.lineWidth=9*s;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-14*s,bodyY+7*s);ctx.lineTo((-25-run*8)*s,bodyY+20*s);ctx.stroke();ctx.beginPath();ctx.moveTo(14*s,bodyY+7*s);ctx.lineTo((25+run*8)*s,bodyY+17*s);ctx.stroke();
  // head and cap
  const headY=bodyY-12*s;ctx.fillStyle='#b87355';ctx.beginPath();ctx.arc(0,headY,12*s,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#233a51';ctx.beginPath();ctx.arc(0,headY-4*s,12*s,Math.PI,Math.PI*2);ctx.lineTo(13*s,headY-2*s);ctx.quadraticCurveTo(3*s,headY+1*s,-12*s,headY);ctx.fill();
  ctx.fillStyle='#5be3dc';rounded(-11*s,headY-5*s,18*s,4*s,2*s);ctx.fill();
  ctx.restore();
}
function drawWorld(){
  drawBackground();
  const sorted=objects.slice().sort((a,b)=>b.z-a.z);
  for(const o of sorted){if(o.kind==='coin')drawCoin(o);else drawObstacle(o)}
  drawPlayer();
  for(const p of particles){ctx.globalAlpha=p.life/p.max;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r*(p.life/p.max),0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
}

