  function drawWorld(){
    drawBackground();
    const sorted=objects.slice().sort((a,b)=>b.z-a.z);
    for(const o of sorted){if(o.kind==='coin')drawCoin(o);else drawObstacle(o)}
    drawPlayer();
    for(const p of particles){ctx.globalAlpha=p.life/p.max;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r*(p.life/p.max),0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
  }
  function addCoins(l,z,count=5){for(let i=0;i<count;i++)objects.push({kind:'coin',lane:l,z:z+i*5,phase:Math.random()*6})}
  function spawnPattern(){
    const base=105, r=Math.random(), safe=Math.floor(Math.random()*3);
    if(r<.25){addCoins(safe,base,6);return}
    if(r<.47){
      const blocked=lanes.filter(l=>l!==safe);const type=Math.random()<.54?'barrier':'beam';
      for(const l of blocked)objects.push({kind:'obstacle',type,lane:l,z:base});addCoins(safe,base+8,4);return;
    }
    if(r<.65){
      const l=lanes[Math.floor(Math.random()*3)];objects.push({kind:'obstacle',type:'train',lane:l,z:base});
      addCoins(l===0?(Math.random()<.5?-1:1):0,base+5,4);return;
    }
    // coin arc with one simple obstacle to hop or duck
    const l=lanes[Math.floor(Math.random()*3)],type=Math.random()<.55?'barrier':'beam';
    objects.push({kind:'obstacle',type,lane:l,z:base});addCoins(l,base-3,3);addCoins(l,base+15,3);
  }
  function update(dt){
    if(state==='running'){
      elapsed+=dt;speed=Math.min(43,24+distance*.006);distance+=speed*dt*.8;
      spawnIn-=speed*dt;if(spawnIn<=0){spawnPattern();spawnIn=rand(27,39)}
      laneVisual+=(lane-laneVisual)*Math.min(1,dt*13);
      if(jump>0)jump=Math.max(0,jump-dt);if(slide>0)slide=Math.max(0,slide-dt);if(hitCooldown>0)hitCooldown-=dt;
      for(const o of objects){o.z-=speed*dt;
        if(o.kind==='coin'&&o.z<4&&o.z>-2&&o.lane===lane){o.taken=true;coins++;scorePop(o.lane);}
        if(o.kind==='obstacle'&&!o.hit&&o.z<5&&o.z>-2&&o.lane===lane&&hitCooldown<=0){
          const cleared=(o.type==='barrier'&&jump>.08)||(o.type==='beam'&&slide>.08);
          if(!cleared){o.hit=true;crash();}
        }
      }
      objects=objects.filter(o=>o.z>-7&&!o.taken);
      for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=35*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);
      ui.distance.textContent=String(Math.floor(distance)).padStart(4,'0');ui.coins.textContent=coins;
    }else{
      elapsed+=dt*.32;laneVisual+=(lane-laneVisual)*Math.min(1,dt*4);
      if(state==='ready'){objects=objects.filter(o=>o.z>-4);if(objects.length<8){const l=lanes[Math.floor(Math.random()*3)];addCoins(l,rand(78,120),4)}}
    }
    if(shake>0)shake=Math.max(0,shake-dt*24);
  }
  function scorePop(l){
    const x=laneX(l,0),y=geometry().gy-80;for(let i=0;i<5;i++)particles.push({x,y,vx:rand(-45,45),vy:rand(-75,-20),r:rand(2,4),life:.42,max:.42,color:'#ffd45e'});
  }
  function crash(){
    if(state!=='running')return;state='over';shake=9;ui.flash.classList.remove('on');void ui.flash.offsetWidth;ui.flash.classList.add('on');
    best=Math.max(best,Math.floor(distance));localStorage.setItem('metrodash-best',best);ui.best.textContent=String(best).padStart(4,'0');
    ui.eyebrow.textContent='Run complete';ui.title.innerHTML=`Nice run<span>Keep going</span>`;ui.message.innerHTML=`You made it <b style="color:#fff">${Math.floor(distance)}m</b> and collected <b style="color:#ffd45e">${coins} coins</b>. One more run?`;
    ui.button.textContent='Run it back  ↗';setTimeout(()=>ui.overlay.classList.remove('hidden'),420);
  }
  function start(){
    state='running';distance=0;coins=0;speed=24;spawnIn=14;lane=0;laneVisual=0;jump=slide=hitCooldown=0;objects=[];particles=[];elapsed=0;
    ui.distance.textContent='0000';ui.coins.textContent='0';ui.overlay.classList.add('hidden');ui.hint.classList.remove('hidden');
    for(let i=0;i<3;i++){const l=lanes[i];addCoins(l,65+i*15,4)}
  }
  function action(a){
    if(state!=='running')return;
    if(a==='left')lane=Math.max(-1,lane-1);if(a==='right')lane=Math.min(1,lane+1);
    if(a==='jump'&&jump<=0&&slide<=0)jump=.72;
    if(a==='slide'&&jump<=0)slide=.64;
  }
  window.addEventListener('keydown',e=>{
    const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup','arrowdown',' ','w','a','s','d'].includes(k))e.preventDefault();
    if(state!=='running'&&(k==='enter'||k===' ')){start();return}
    if(k==='arrowleft'||k==='a')action('left');if(k==='arrowright'||k==='d')action('right');if(k==='arrowup'||k==='w'||k===' ')action('jump');if(k==='arrowdown'||k==='s')action('slide');
  });
  ui.button.addEventListener('click',start);
  document.querySelectorAll('.mobile-controls button').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();action(b.dataset.action)}));
  let touchStart=null;
  canvas.addEventListener('pointerdown',e=>{touchStart={x:e.clientX,y:e.clientY};});
  canvas.addEventListener('pointerup',e=>{
    if(!touchStart)return;const dx=e.clientX-touchStart.x,dy=e.clientY-touchStart.y;touchStart=null;
    if(Math.max(Math.abs(dx),Math.abs(dy))<24)return;
    if(Math.abs(dx)>Math.abs(dy))action(dx<0?'left':'right');else action(dy<0?'jump':'slide');
